92	export class BackgroundManager implements BackgroundManagerRuntimePort {
93	  private static readonly _CLASS = "BackgroundManager";
94	  private readonly _renderer: THREE.WebGLRenderer;
95	  private readonly _scene: THREE.Scene;
96	  private readonly _camera: THREE.Camera;
97	  private readonly _backgroundScene = new THREE.Scene();
98	  private readonly _backgroundCamera = new THREE.OrthographicCamera(
99	    -1,
100	    1,
101	    1,
102	    -1,
103	    0,
104	    1,
105	  );
106	  private readonly _geometry = new THREE.PlaneGeometry(2, 2);
107	  private readonly _entries = new Map<string, BackgroundManagerEntry>();
108	  private readonly _anchor = new THREE.Vector2(0.5, 0.5);
109	  private readonly _anchorTarget = new THREE.Vector2(0.5, 0.5);
110	  private readonly _cameraEuler = new THREE.Euler(0, 0, 0, "YXZ");
111	  private readonly _displayRenderTarget: THREE.WebGLRenderTarget;
112	  private readonly _variantRenderTarget: THREE.WebGLRenderTarget;
113	  private readonly _transitionFromRenderTarget: THREE.WebGLRenderTarget;
114	  private readonly _mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
115	  private readonly _copyMaterial: THREE.ShaderMaterial;
116	  private readonly _transitionMaterial: THREE.ShaderMaterial;
117	  private readonly _displacementTexture: THREE.DataTexture;
118	  private readonly _heroNoiseTexture: THREE.DataTexture;
119	  private readonly _materialRuntime: BackgroundMaterialRuntime;
120	  private readonly _initialBackground:
121	    | THREE.Color
122	    | THREE.Texture
123	    | THREE.CubeTexture
124	    | null;
125	  private _elapsedTime = 0;
126	  private _activeEntryId: string | null = null;
127	  private readonly _lookScratch: Required<BackgroundLookOptions> = {
128	    ...BACKGROUND_DEFAULT_LOOK,
129	  };
130	  private _hasRenderedFrame = false;
131	  private _rendererExposureSnapshot: number | null = null;
132	  private _transitionElapsed = 0;
133	  private _transitionActive = false;
134	  private readonly _lastVisibilityById = new Map<string, boolean>();
135	  private _getPerformanceProfile() {
136	    return ResponsiveRuntime.getDefault().getSnapshot().performance;
137	  }
138	
139	  constructor(
140	    renderer: THREE.WebGLRenderer,
141	    scene: THREE.Scene,
142	    camera: THREE.Camera,
143	  ) {
144	    this._renderer = renderer;
145	    this._scene = scene;
146	    this._camera = camera;
147	    this._initialBackground = this._cloneSceneBackground(scene.background);
148	    this._displayRenderTarget = new THREE.WebGLRenderTarget(
149	      BACKGROUND_DEFAULT_RESOLUTION,
150	      BACKGROUND_DEFAULT_RESOLUTION,
151	      {
152	        depthBuffer: false,
153	        stencilBuffer: false,
154	      },
155	    );
156	    this._variantRenderTarget = new THREE.WebGLRenderTarget(
157	      BACKGROUND_DEFAULT_RESOLUTION,
158	      BACKGROUND_DEFAULT_RESOLUTION,
159	      {
160	        depthBuffer: false,
161	        stencilBuffer: false,
162	      },
163	    );
164	    this._transitionFromRenderTarget = new THREE.WebGLRenderTarget(
165	      BACKGROUND_DEFAULT_RESOLUTION,
166	      BACKGROUND_DEFAULT_RESOLUTION,
167	      {
168	        depthBuffer: false,
169	        stencilBuffer: false,
170	      },
171	    );
172	    this._copyMaterial = new THREE.ShaderMaterial({
173	      uniforms: {
174	        uTexture: { value: null },
175	      },
176	      vertexShader: fullscreenVertexShader,
177	      fragmentShader: COPY_FRAGMENT_SHADER,
178	      depthWrite: false,
179	      depthTest: false,
180	      transparent: false,
181	      toneMapped: false,
182	    });
183	    this._transitionMaterial = new THREE.ShaderMaterial({
184	      uniforms: {
185	        time: { value: 0 },
186	        progress: { value: 0 },
187	        width: { value: BACKGROUND_TRANSITION_CONFIG.width },
188	        radius: { value: BACKGROUND_TRANSITION_CONFIG.radius },
189	        displacementIntensity: {
190	          value: BACKGROUND_TRANSITION_CONFIG.displacementIntensity,
191	        },
192	        texture1: { value: this._transitionFromRenderTarget.texture },
193	        texture2: { value: this._variantRenderTarget.texture },
194	        displacement: { value: null },
195	        resolution: { value: new THREE.Vector4(1, 1, 1, 1) },
196	      },
197	      vertexShader: fullscreenVertexShader,
198	      fragmentShader: backgroundTransitionFragmentShader,
199	      depthWrite: false,
200	      depthTest: false,
201	      transparent: false,
202	      toneMapped: false,
203	    });
204	    this._displacementTexture = this._createDisplacementTexture();
205	    this._heroNoiseTexture = this._createNoiseTexture(
206	      BACKGROUND_HERO_NOISE_TEXTURE_SIZE,
207	    );
208	    this._materialRuntime = new BackgroundMaterialRuntime(
209	      () => ({
210	        width: this._displayRenderTarget.width,
211	        height: this._displayRenderTarget.height,
212	      }),
213	      this._heroNoiseTexture,
214	      () => this._getPerformanceProfile().heroRaymarchSteps,
215	    );
216	    (this._transitionMaterial.uniforms.displacement
217	      .value as THREE.DataTexture | null) = this._displacementTexture;
218	    this._mesh = new THREE.Mesh(
219	      this._geometry,
