231	  register(
232	    id: string,
233	    options: Partial<BackgroundObjectOptions> = {},
234	    runtimeState: Partial<BackgroundRuntimeState> = {},
235	  ): void {
236	    const current = this._entries.get(id);
237	    if (current) {
238	      this.setOptions(id, options);
239	      this.setRuntimeState(id, runtimeState);
240	      return;
241	    }
242	    this._entries.set(id, {
243	      id,
244	      options: { ...options },
245	      runtimeState: { ...runtimeState },
246	      shaderTimeOffset: this._elapsedTime,
247	    });
248	    this._resolveActiveEntryId();
249	  }
250	
251	  resetShaderClock(id: string): void {
252	    const entry = this._entries.get(id);
253	    if (!entry) return;
254	    entry.shaderTimeOffset = this._elapsedTime;
255	  }
256	
257	  unregister(id: string): void {
258	    this._entries.delete(id);
259	    if (this._activeEntryId !== id) {
260	      this._resolveActiveEntryId();
261	      return;
262	    }
263	    this._activeEntryId = null;
264	    this._resolveActiveEntryId();
265	    if (this._activeEntryId) return;
266	    this._restoreSceneBackground();
267	    this._restoreRendererExposure();
268	  }
269	
270	  setOptions(id: string, options: Partial<BackgroundObjectOptions>): void {
271	    const entry = this._entries.get(id);
272	    if (!entry) return;
273	    const previousVisible = this._isVisible(entry.options);
274	    entry.options = {
275	      ...entry.options,
276	      ...options,
277	      look: this._mergeLook(entry.options.look, options.look),
278	    };
279	    const nextVisible = this._isVisible(entry.options);
280	    if (this._lastVisibilityById.get(id) !== nextVisible) {
281	      this._lastVisibilityById.set(id, nextVisible);
282	    }
283	    this._resolveActiveEntryId();
284	  }
285	
286	  setRuntimeState(id: string, state: Partial<BackgroundRuntimeState>): void {
287	    const entry = this._entries.get(id);
288	    if (!entry) return;
289	    const nextState = {
290	      ...entry.runtimeState,
291	      ...state,
292	    };
293	    if ("look" in state) {
294	      nextState.look = state.look ? { ...state.look } : undefined;
295	    }
296	    if ("shaderControls" in state) {
297	      nextState.shaderControls = state.shaderControls
298	        ? { ...state.shaderControls }
299	        : undefined;
300	    }
301	    entry.runtimeState = nextState;
302	  }
303	
304	  getRuntimeState(id: string): BackgroundRuntimeState {
305	    return { ...(this._entries.get(id)?.runtimeState ?? {}) };
306	  }
307	
308	  hasRenderedFrame(): boolean {
309	    return this._hasRenderedFrame;
310	  }
311	
312	  startTransition(id: string): void {
313	    if (!this._getPerformanceProfile().transitionEnabled) return;
314	    if (!this._entries.has(id) || !this._hasRenderedFrame) return;
315	    this._copyToTarget(
316	      this._displayRenderTarget.texture,
317	      this._transitionFromRenderTarget,
318	    );
319	    this._transitionElapsed = 0;
320	    this._transitionActive = true;
321	  }
322	
323	  update(deltaTime: number): void {
324	    this._elapsedTime += Number.isFinite(deltaTime)
325	      ? Math.max(0, deltaTime)
326	      : 0;
327	    this._updateAnchor(deltaTime);
328	    if (!this._transitionActive) return;
329	    this._transitionElapsed = Math.min(
330	      BACKGROUND_TRANSITION_CONFIG.duration,
331	      this._transitionElapsed + Math.max(0, deltaTime),
332	    );
333	    if (this._transitionElapsed < BACKGROUND_TRANSITION_CONFIG.duration) return;
334	    this._transitionActive = false;
335	  }
336	
337	  render(): void {
338	    const entry = this._getActiveEntry();
339	    if (!entry) {
340	      this._restoreSceneBackground();
341	      this._restoreRendererExposure();
342	      return;
343	    }
344	
345	    const variant = this._resolveVariant(entry);
346	    const material = this._materialRuntime.getMaterial(variant);
347	    this._applyUniforms(material, entry, variant);
348	    this._applyExposure(entry);
349	    this._renderFullscreen(material, this._variantRenderTarget);
350	    if (
351	      this._transitionActive &&
352	      this._getPerformanceProfile().transitionEnabled
353	    ) {
354	      this._renderTransition();
355	    } else {
356	      this._copyToTarget(
357	        this._variantRenderTarget.texture,
358	        this._displayRenderTarget,
359	      );
360	    }
361	    this._hasRenderedFrame = true;
362	    if (this._scene.background !== this._displayRenderTarget.texture) {
363	      this._scene.background = this._displayRenderTarget.texture;
364	    }
365	    this._scene.backgroundIntensity = 1;
366	  }
367	
368	  resize(width: number, height: number, pixelRatio = 1): void {
369	    const performance = this._getPerformanceProfile();
370	    const renderWidth = Math.max(
371	      BACKGROUND_DEFAULT_RESOLUTION,
372	      Math.round(width * pixelRatio * performance.backgroundResolutionScale),
373	    );
374	    const renderHeight = Math.max(
375	      BACKGROUND_DEFAULT_RESOLUTION,
376	      Math.round(height * pixelRatio * performance.backgroundResolutionScale),
377	    );
378	    this._displayRenderTarget.setSize(renderWidth, renderHeight);
379	    this._variantRenderTarget.setSize(renderWidth, renderHeight);
380	    this._transitionFromRenderTarget.setSize(renderWidth, renderHeight);
381	    this._materialRuntime.resize();
382	    const resolution = this._transitionMaterial.uniforms.resolution.value;
383	    if (resolution instanceof THREE.Vector4) {
384	      resolution.set(renderWidth, renderHeight, 1, 1);
385	    }
386	  }
387	
388	  dispose(): void {
389	    this._restoreSceneBackground();
390	    this._restoreRendererExposure();
391	    this._materialRuntime.dispose();
392	    this._geometry.dispose();
393	    this._displayRenderTarget.dispose();
394	    this._variantRenderTarget.dispose();
395	    this._transitionFromRenderTarget.dispose();
396	    this._copyMaterial.dispose();
397	    this._transitionMaterial.dispose();
398	    this._displacementTexture.dispose();
399	    this._heroNoiseTexture.dispose();
400	    this._entries.clear();
401	  }
402	
403	  private _getActiveEntry(): BackgroundManagerEntry | null {
404	    this._resolveActiveEntryId();
405	    if (!this._activeEntryId) return null;
406	    return this._entries.get(this._activeEntryId) ?? null;
407	  }
408	
409	  private _resolveActiveEntryId(): void {
410	    const current = this._activeEntryId
411	      ? this._entries.get(this._activeEntryId)
412	      : null;
413	    if (current && this._isVisible(current.options)) return;
414	    this._activeEntryId = null;
415	    for (const entry of this._entries.values()) {
416	      if (!this._isVisible(entry.options)) continue;
417	      this._activeEntryId = entry.id;
418	      return;
419	    }
420	  }
421	
422	  private _applyUniforms(
423	    material: THREE.ShaderMaterial,
424	    entry: BackgroundManagerEntry,
425	    variant: BackgroundVariantKey,
426	  ): void {
427	    const uniforms = material.uniforms as BackgroundUniformRecord;
428	    const performance = this._getPerformanceProfile();
429	    const look = this._resolveLook(entry, variant);
430	    (uniforms.uTime.value as number) = Math.max(
431	      0,
432	      this._elapsedTime - entry.shaderTimeOffset,
433	    );
434	    (uniforms.uAnchor.value as THREE.Vector2).copy(this._anchor);
435	    (uniforms.uPointer.value as THREE.Vector2).set(0.5, 0.5);
436	    (uniforms.uPointerVelocity.value as THREE.Vector2).set(0, 0);
437	    (uniforms.uPointerStrength.value as number) = 0;
