334	  private _createCurvedPlaneGeometry(): THREE.PlaneGeometry {
335	    const plane = this._resolvePlaneOptions();
336	    const geometry = new THREE.PlaneGeometry(
337	      plane.width,
338	      plane.height,
339	      plane.segments,
340	      plane.segments,
341	    );
342	    if (plane.curveDepth <= 0 || plane.segments <= 1) {
343	      geometry.computeVertexNormals();
344	      geometry.computeBoundingSphere();
345	      return geometry;
346	    }
347	    const position = geometry.getAttribute("position");
348	    for (let index = 0; index < position.count; index += 1) {
349	      const x = position.getX(index);
350	      const y = position.getY(index);
351	      const normalizedX = Math.abs(x / (plane.width * 0.5));
352	      const normalizedY = Math.abs(y / (plane.height * 0.5));
353	      const clampedX = THREE.MathUtils.clamp(normalizedX, 0, 1);
354	      const clampedY = THREE.MathUtils.clamp(normalizedY, 0, 1);
355	      const edgeCurve = this._smoothstep(
356	        0.72,
357	        1,
358	        Math.pow(clampedX, plane.curvePower),
359	      );
360	      const horizontalCurve =
361	        (1 - Math.cos(edgeCurve * Math.PI * 0.5)) * edgeCurve;
362	      const verticalCurve = 1 - Math.pow(clampedY, 1.5) * 0.03;
363	      position.setZ(
364	        index,
365	        plane.curveDepth *
366	          horizontalCurve *
367	          THREE.MathUtils.clamp(verticalCurve, 0.96, 1),
368	      );
369	    }
370	    position.needsUpdate = true;
371	    geometry.computeVertexNormals();
372	    geometry.computeBoundingSphere();
373	    return geometry;
